class BillingPublic(Resource):
    """What a publishable key (``pk_...``) reaches: the public catalog and anonymous checkouts.

    Build the client with the key as its token -- the SDK sends it as the API requires, in
    ``X-Kaiten-Publishable-Key`` and never as a bearer token::

        public = KaitenClient(base_url="https://kaiten.example.com", token="pk_...")
        catalog = public.billing.public.get_catalog()

    An anonymous checkout's own routes take the token it was started with (``ksc_...``)
    instead: build a client with that token to read or confirm it.
    """

    def get_catalog(
        self, *, family_slug: str | None = None, include_addons: bool = True
    ) -> PublicCatalog:
        """Return what a pricing page shows: the public plans, their prices and entitlements.

        For each license family the organization made public, its default version with its
        ``ACTIVE`` prices and user-facing entitlements, and the same for public add-on
        families. Amounts are in minor units: never sum metered prices into a headline.

        Args:
            family_slug: Only this license family.
            include_addons: Also list the public add-ons. True by default.
        """
        return self._api.get(
            "/public/catalog",
            PublicCatalog,
            params={"familySlug": family_slug, "include": None if include_addons else ["none"]},
        )

    def create_checkout_session(
        self,
        *,
        turnstile_token: str,
        price_id: str | None = None,
        license_slug: str | None = None,
        billing_period: BillingPeriod | None = None,
        add_ons: Mapping[str, int] | None = None,
        email: str | None = None,
        return_url: str | None = None,
        voucher_code: str | None = None,
        trial: bool | None = None,
        client_reference_id: str | None = None,
        dry_run: bool | None = None,
    ) -> CheckoutSessionStart:
        """Start a checkout for a visitor your backend does not know yet.

        It writes one checkout session and nothing else: the customer, the instance and the
        subscription are created when it completes. The session's token (``ksc_...``) is in
        this response only. The key must allow anonymous checkouts.

        Args:
            turnstile_token: The token the Turnstile widget gave the page. Single-use.
            price_id: A ``FLAT_FEE`` price of a public plan. Not with ``license_slug``.
            license_slug: A public plan's version, with ``billing_period``: its default
                ``ACTIVE`` ``FLAT_FEE`` price of that period.
            billing_period: ``MONTHLY``, ``QUARTERLY``, ``SEMI_ANNUAL`` or ``ANNUAL``.
            add_ons: Public add-ons, as ``{addon_slug: quantity}``.
            email: The buyer's e-mail, which becomes the new customer's billing e-mail. Required
                unless ``dry_run``.
            return_url: Where the payment-method page sends the visitor back, on an origin the
                key allows. Required unless ``dry_run``.
            voucher_code: A code to apply to the selection.
            trial: ``False`` declines the license's trial.
            client_reference_id: Your own reference, echoed on the ``checkout_session`` events.
            dry_run: Compute what would be due today, and write nothing.
        """
        body = {
            "turnstileToken": turnstile_token,
            **compact(
                {
                    "priceId": price_id,
                    "licenseSlug": license_slug,
                    "billingPeriod": billing_period,
                    "addOns": addon_quantities(add_ons),
                    "email": email,
                    "returnUrl": return_url,
                    "voucherCode": voucher_code,
                    "trial": trial,
                    "clientReferenceId": client_reference_id,
                    "dryRun": dry_run,
                }
            ),
        }
        return self._api.send("POST", "/public/checkout-sessions", CheckoutSessionStart, body=body)

    def get_checkout_session(self, session_id: str) -> CheckoutSession:
        """Return the checkout session the client's ``ksc_`` token was minted for.

        Its status, what it bought and what is due, and once completed, the customer and
        instance it created. The token reads it for 24 hours after it closed.
        """
        return self._api.get(api_path("public", "checkout-sessions", session_id), CheckoutSession)

    def confirm_checkout_session(self, session_id: str) -> CheckoutConfirmation:
        """Complete the checkout session when nothing has to be captured, or say what is missing.

        A free plan, a trial that needs no payment method, or nothing due completes it at once:
        ``completed``. Otherwise ``requires_payment_method`` comes with the page where the
        visitor saves one, and the next confirmation completes it.
        """
        return self._api.send(
            "POST",
            api_path("public", "checkout-sessions", session_id, "confirm"),
            CheckoutConfirmation,
        )


class BillingSession(Resource):
    """What a customer session (``kst_...``) reaches: one customer's own billing.

    These are the routes a customer's page calls with the session your backend minted with
    :meth:`BillingCustomerSessions.create`. Build the client with the session's token to
    call them from Python::

        customer = KaitenClient(base_url="https://kaiten.example.com", token=session.token)
        portal = customer.billing.session.get_portal()

    The subscription routes need a session bound to an instance.
    """

    def get_portal(self) -> SessionPortal:
        """Return everything the customer's portal shows, in one read.

        The customer, and for a session bound to an instance its subscription, effective quotas
        with where they come from, add-ons, vouchers and next invoice; the payment method; and
        what the portal may offer.
        """
        return self._api.get("/public/session/portal", SessionPortal)

    def list_invoices(self, *, limit: int | None = None) -> builtins.list[SessionInvoice]:
        """Return the customer's issued invoices, newest first, with how to pay each.

        Args:
            limit: The most invoices to return. Every page is walked when omitted.
        """
        return self._api.list_all(
            "/public/session/invoices", SessionInvoice, limit=check_limit(limit)
        )

    def checkout(
        self,
        *,
        license_price_id: str,
        add_ons: Mapping[str, int] | None = None,
        voucher_code: str | None = None,
        billing_email: str | None = None,
        return_url: str | None = None,
        setup_session_id: str | None = None,
        trial: bool | None = None,
        dry_run: bool | None = None,
    ) -> SessionCheckout:
        """Subscribe the session's instance to a price of the public catalog, in one call.

        ``status`` says what happened: ``preview`` for a dry run, ``requires_payment_method``
        with the page where the customer saves one -- call again with its ``setup_session_id``
        afterwards -- or ``subscribed``.

        Args:
            license_price_id: An ``ACTIVE`` flat-fee price of a public plan.
            add_ons: Public add-ons that fit the plan, as ``{addon_slug: quantity}``.
            voucher_code: A code to redeem with the checkout.
            billing_email: Where invoices go; required when the customer has none.
            return_url: Where the payment-method page sends the customer back.
            setup_session_id: The setup session a ``requires_payment_method`` answer gave.
            trial: ``False`` skips the plan's trial.
            dry_run: Answer what the checkout would bill today, and change nothing.
        """
        body = {
            "licensePriceId": license_price_id,
            **compact(
                {
                    "addOns": addon_quantities(add_ons),
                    "voucherCode": voucher_code,
                    "billingEmail": billing_email,
                    "returnUrl": return_url,
                    "setupSessionId": setup_session_id,
                    "trial": trial,
                    "dryRun": dry_run,
                }
            ),
        }
        return self._api.send("POST", "/public/session/checkout", SessionCheckout, body=body)

    def cancel(self, *, reason: str | None = None) -> SessionSubscription:
        """Cancel the instance's subscription at the end of the period paid for.

        It keeps billing and granting until then. A trial ends at once. Repeating it changes
        nothing.

        Args:
            reason: Why the customer cancels, up to 500 characters; you see it on the
                subscription.
        """
        return self._api.send(
            "POST",
            "/public/session/billing/cancel",
            SessionSubscription,
            body=compact({"reason": reason}),
            idempotent=True,
        )

    def reactivate(self) -> SessionSubscription:
        """Take back a cancellation scheduled for the period's end, before it."""
        return self._api.send("POST", "/public/session/billing/reactivate", SessionSubscription)

    def set_addon_quantity(self, addon_slug: str, quantity: int) -> SessionAddon:
        """Attach a public add-on to the instance, change its quantity, or remove it with ``0``.

        With a live subscription, a lower quantity is scheduled for the next renewal:
        ``pending_quantity`` shows it.
        """
        return self._api.send(
            "PUT",
            api_path("public", "session", "addons", addon_slug),
            SessionAddon,
            body={"quantity": quantity},
        )

    def create_payment_method_session(
        self, *, return_url: str, currency: str | None = None
    ) -> PaymentMethodSession:
        """Open the payment provider's page where the customer saves a payment method.

        Args:
            return_url: Where the page sends the customer back, on an origin one of the
                organization's publishable keys allows.
            currency: Required when the customer has no live subscription.
        """
        return self._api.send(
            "POST",
            "/public/session/billing/payment-method-session",
            PaymentMethodSession,
            body={"returnUrl": return_url, **compact({"currency": currency})},
        )

    def complete_payment_method_session(self, session_id: str) -> CompletedPaymentMethodSession:
        """Check a setup session with the provider, and charge the customer's invoices to it.

        Safe to repeat.
        """
        return self._api.send(
            "POST",
            api_path(
                "public", "session", "billing", "payment-method-session", session_id, "complete"
            ),
            CompletedPaymentMethodSession,
            idempotent=True,
        )

    def create_portal_session(self, *, return_url: str) -> PortalSession:
        """Open the payment provider's portal for the customer.

        Args:
            return_url: Where the portal sends the customer back, on an origin one of the
                organization's publishable keys allows.
        """
        return self._api.send(
            "POST",
            "/public/session/billing/portal-session",
            PortalSession,
            body={"returnUrl": return_url},
        )

    def validate_voucher(
        self, code: str, *, license_price_id: str | None = None
    ) -> SessionVoucherValidity:
        """Say whether a code would apply to the customer, with what it gives. Nothing is redeemed.

        Args:
            code: The code as the customer typed it.
            license_price_id: The price about to be checked out.
        """
        body = {"code": code, **compact({"licensePriceId": license_price_id})}
        return self._api.send(
            "POST", "/public/session/vouchers/validate", SessionVoucherValidity, body=body
        )

    def redeem_voucher(self, code: str, *, dry_run: bool | None = None) -> SessionRedemption:
        """Redeem a code on the instance, and return the redemption -- never the code.

        Args:
            code: The code as the customer typed it.
            dry_run: Answer the redemption it would make, and write nothing.
        """
        body = {"code": code, **compact({"dryRun": dry_run})}
        return self._api.send(
            "POST", "/public/session/vouchers/redeem", SessionRedemption, body=body
        )
